mapper.update:
UPDATE zabbix.sla_review_event
SET owner_name = #{ownerName},
    updated_at = CURRENT_TIMESTAMP
WHERE period_month = #{periodMonth}
  AND system_level = #{systemLevel}
  AND system_name = #{systemName}
  AND down_start = #{downStart}

mapper.select:
SELECT id, period_month, system_level, system_name, down_start, down_end,
       exclude_time, owner_name, fault_category, fault_subcategory, fault_desc, count_sla,
       resolution_process, root_cause, improvement, created_at, updated_at
FROM zabbix.sla_review_event
WHERE period_month = #{periodMonth}
  AND system_level = #{systemLevel}
  AND system_name = #{systemName}
  AND down_start = #{downStart}

SELECT id, fault_category, fault_subcategory, fault_desc, count_sla, sort_order
FROM zabbix.sla_fault_category
WHERE fault_category = #{faultCategory}
  AND fault_subcategory = #{faultSubcategory}
LIMIT 1
